-- dishes table
create table if not exists dishes (
  id text primary key,
  name text not null,
  image_url text,
  description text,
  cook_time int,
  servings int,
  cuisine text
);

-- ingredients table
create table if not exists ingredients (
  id uuid primary key default gen_random_uuid(),
  dish_id text references dishes(id) on delete cascade,
  name text not null,
  quantity text,
  unit text,
  price_estimate numeric(6,2)
);

-- cart_orders table
create table if not exists cart_orders (
  id uuid primary key default gen_random_uuid(),
  user_session text,
  items jsonb,
  total numeric(8,2),
  created_at timestamptz default now()
);

